def c(id,name,gloss,req,ev,known=False,title=None,symbols=None,aliases=None):
    d=dict(id=id,name=name,aliases=aliases or [],gloss=gloss,requires=req,known=known,
      evidence=[dict(source=P,quote=q) for q in ev])
    if title: d["title"]=title; d["symbols"]=symbols
    return d
